{
  "compilerOptions": {
    "target": "ES2017",
    "lib": ["dom", "dom.iterable", "esnext"],
    "allowJs": true,
    "skipLibCheck": true,
    "strict": true,
    "noEmit": true,
    "esModuleInterop": true,
    "module": "esnext",
    "moduleResolution": "bundler",
    "resolveJsonModule": true,
    "isolatedModules": true,
    "jsx": "preserve",
    "incremental": true,
    "plugins": [
      {
        "name": "next"
      }
    ],
    "paths": {
      "@/*": ["./*"]
    }
  },
  "include": ["next-env.d.ts", "**/*.ts", "**/*.tsx", ".next/types/**/*.ts"],
  "exclude": ["node_modules"]
}

:root {
  --font-sans: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --color-bg: #f9fafb;
  --color-surface: #ffffff;
  --color-primary: #6c3a2d;
  --color-primary-hover: #5a2f22;
  --color-muted: #6b7280;
  --color-border: #e5e7eb;
  --radius: 4px;
  --spacing: 8px;
  --transition: 150ms ease;
}
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}
body {
  font-family: var(--font-sans);
  background: var(--color-bg);
  color: #111827;
  line-height: 1.5;
}
h1,
h2,
h3,
h4 {
  font-weight: 600;
  margin-bottom: var(--spacing);
}
h1 {
  font-size: 1.75rem;
}
h2 {
  font-size: 1.5rem;
}
h3 {
  font-size: 1.25rem;
}
.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: var(--spacing);
}
.sidebar {
  width: 240px;
  background: var(--color-surface);
  border-right: 1px solid var(--color-border);
  height: 100vh;
  position: fixed;
  top: 0;
  left: 0;
  padding: var(--spacing);
}
.main {
  margin-left: 240px;
  padding: var(--spacing);
}
.button {
  display: inline-block;
  padding: calc(var(--spacing) * 0.75) calc(var(--spacing) * 1.5);
  background: var(--color-primary);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  cursor: pointer;
  transition: background var(--transition);
  font-size: 0.9375rem;
}
.button:hover {
  background: var(--color-primary-hover);
}
.input {
  padding: calc(var(--spacing) * 0.75) var(--spacing);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  font-size: 0.9375rem;
  width: 100%;
  transition: border-color var(--transition);
}
.input:focus {
  outline: none;
  border-color: var(--color-primary);
}
.table {
  width: 100%;
  border-collapse: collapse;
  margin-top: var(--spacing);
}
.table th,
.table td {
  padding: var(--spacing);
  border-bottom: 1px solid var(--color-border);
  text-align: left;
  font-size: 0.9375rem;
}
.table th {
  background: var(--color-surface);
  cursor: pointer;
}
.table tr:hover {
  background: #f3f4f6;
}
.badge {
  display: inline-block;
  padding: 0 0.5rem;
  border-radius: var(--radius);
  font-size: 0.75rem;
  font-weight: 500;
  text-transform: uppercase;
}
.badge-pending {
  background: #fde68a;
  color: #92400e;
}
.badge-roasting {
  background: #fca5a5;
  color: #7f1d1d;
}
.badge-ready {
  background: #bbf7d0;
  color: #166534;
}
.badge-shipped {
  background: #c7d2fe;
  color: #3730a3;
}
.filter-chip {
  display: inline-block;
  padding: calc(var(--spacing) * 0.5) var(--spacing);
  border: 1px solid var(--color-border);
  border-radius: var(--radius);
  margin-right: var(--spacing);
  cursor: pointer;
  font-size: 0.8125rem;
}
.filter-chip.active {
  background: var(--color-primary);
  color: #fff;
  border-color: var(--color-primary);
}
.fade-enter {
  opacity: 0;
  transition: opacity var(--transition);
}
.fade-enter-active {
  opacity: 1;
}
.fade-exit {
  opacity: 1;
  transition: opacity var(--transition);
}
.fade-exit-active {
  opacity: 0;
}

import { promises as fs } from 'fs';
import path from 'path';

export type RoastBatchStatus = 'Pending' | 'Roasting' | 'Ready' | 'Shipped';

export interface Order {
  id: string;
  customerId: string;
  subscriptionDate: string;
  quantityG: number;
  roastBatchId: string;
  status: RoastBatchStatus;
  totalPrice: number;
}

export interface Customer {
  id: string;
  name: string;
  email: string;
  address: string;
  subscriptionPlan: string;
}

const dataFile = path.join(process.cwd(), 'data', 'store.json');

interface StoreData {
  orders: Order[];
  customers: Customer[];
}

async function readStore(): Promise<StoreData> {
  try {
    const text = await fs.readFile(dataFile, 'utf8');
    return JSON.parse(text);
  } catch {
    const init: StoreData = { orders: [], customers: [] };
    await fs.mkdir(path.dirname(dataFile), { recursive: true });
    await fs.writeFile(dataFile, JSON.stringify(init, null, 2));
    return init;
  }
}

async function writeStore(data: StoreData): Promise<void> {
  await fs.writeFile(dataFile, JSON.stringify(data, null, 2));
}

export async function getOrders(): Promise<Order[]> {
  const { orders } = await readStore();
  return orders;
}

export async function getCustomers(): Promise<Customer[]> {
  const { customers } = await readStore();
  return customers;
}

export async function addOrder(order: Order): Promise<void> {
  const data = await readStore();
  data.orders.push(order);
  await writeStore(data);
}

export async function updateOrder(id: string, updates: Partial<Order>): Promise<void> {
  const data = await readStore();
  const idx = data.orders.findIndex(o => o.id === id);
  if (idx === -1) throw new Error('Order not found');
  data.orders[idx] = { ...data.orders[idx], ...updates };
  await writeStore(data);
}

export async function addCustomer(customer: Customer): Promise<void> {
  const data = await readStore();
  data.customers.push(customer);
  await writeStore(data);
}

export async function updateCustomer(id: string, updates: Partial<Customer>): Promise<void> {
  const data = await readStore();
  const idx = data.customers.findIndex(c => c.id === id);
  if (idx === -1) throw new Error('Customer not found');
  data.customers[idx] = { ...data.customers[idx], ...updates };
  await writeStore(data);
}

import { NextRequest, NextResponse } from 'next/server';
import { getOrders, getCustomers, addOrder, updateOrder, addCustomer, updateCustomer } from '../../../lib/store';
import type { Order, Customer, RoastBatchStatus } from '../../../lib/store';

const VALID_STATUSES: RoastBatchStatus[] = ['Pending', 'Roasting', 'Ready', 'Shipped'];
const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

function isRecord(value: unknown): value is Record<string, unknown> {
  return !!value && typeof value === 'object';
}

function isValidOrder(value: unknown): value is Order {
  if (!isRecord(value)) return false;
  return (
    typeof value.id === 'string' &&
    typeof value.customerId === 'string' &&
    typeof value.subscriptionDate === 'string' &&
    typeof value.quantityG === 'number' && value.quantityG > 0 &&
    typeof value.roastBatchId === 'string' &&
    typeof value.status === 'string' && VALID_STATUSES.includes(value.status as RoastBatchStatus) &&
    typeof value.totalPrice === 'number' && value.totalPrice >= 0
  );
}

function isValidCustomer(value: unknown): value is Customer {
  if (!isRecord(value)) return false;
  return (
    typeof value.id === 'string' &&
    typeof value.name === 'string' &&
    typeof value.email === 'string' && EMAIL_RE.test(value.email) &&
    typeof value.address === 'string' &&
    typeof value.subscriptionPlan === 'string'
  );
}

export async function GET() {
  try {
    const [orders, customers] = await Promise.all([getOrders(), getCustomers()]);
    return NextResponse.json({ orders, customers });
  } catch {
    return NextResponse.json({ error: 'Could not read the store.' }, { status: 500 });
  }
}

export async function POST(request: NextRequest) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Request body must be valid JSON.' }, { status: 400 });
  }
  if (!isRecord(body)) {
    return NextResponse.json({ error: 'Request body must be an object.' }, { status: 400 });
  }
  try {
    if (body.type === 'order') {
      if (!isValidOrder(body.order)) {
        return NextResponse.json({ error: 'Order data is invalid. Check required fields.' }, { status: 400 });
      }
      await addOrder(body.order);
      return NextResponse.json({ ok: true }, { status: 201 });
    }
    if (body.type === 'customer') {
      if (!isValidCustomer(body.customer)) {
        return NextResponse.json({ error: 'Customer data is invalid. Check required fields.' }, { status: 400 });
      }
      await addCustomer(body.customer);
      return NextResponse.json({ ok: true }, { status: 201 });
    }
    return NextResponse.json({ error: 'Unknown record type. Use "order" or "customer".' }, { status: 400 });
  } catch {
    return NextResponse.json({ error: 'Could not write to the store.' }, { status: 500 });
  }
}

export async function PATCH(request: NextRequest) {
  let body: unknown;
  try {
    body = await request.json();
  } catch {
    return NextResponse.json({ error: 'Request body must be valid JSON.' }, { status: 400 });
  }
  if (!isRecord(body)) {
    return NextResponse.json({ error: 'Request body must be an object.' }, { status: 400 });
  }
  const { type, id, updates } = body;
  if (typeof id !== 'string' || !id) {
    return NextResponse.json({ error: 'A record id is required.' }, { status: 400 });
  }
  if (!isRecord(updates)) {
    return NextResponse.json({ error: 'Updates must be an object.' }, { status: 400 });
  }
  try {
    if (type === 'order') {
      if (updates.status !== undefined && (typeof updates.status !== 'string' || !VALID_STATUSES.includes(updates.status as RoastBatchStatus))) {
        return NextResponse.json({ error: 'Order status must be Pending, Roasting, Ready, or Shipped.' }, { status: 400 });
      }
      if (updates.quantityG !== undefined && (typeof updates.quantityG !== 'number' || updates.quantityG <= 0)) {
        return NextResponse.json({ error: 'Quantity must be a positive number of grams.' }, { status: 400 });
      }
      if (updates.totalPrice !== undefined && (typeof updates.totalPrice !== 'number' || updates.totalPrice < 0)) {
        return NextResponse.json({ error: 'Total price must be a non-negative number.' }, { status: 400 });
      }
      await updateOrder(id, updates as Partial<Order>);
      return NextResponse.json({ ok: true });
    }
    if (type === 'customer') {
      if (updates.email !== undefined && (typeof updates.email !== 'string' || !EMAIL_RE.test(updates.email))) {
        return NextResponse.json({ error: 'Email address is invalid.' }, { status: 400 });
      }
      await updateCustomer(id, updates as Partial<Customer>);
      return NextResponse.json({ ok: true });
    }
    return NextResponse.json({ error: 'Unknown record type. Use "order" or "customer".' }, { status: 400 });
  } catch (error) {
    if (error instanceof Error && error.message === 'Order not found') {
      return NextResponse.json({ error: 'Order not found.' }, { status: 404 });
    }
    if (error instanceof Error && error.message === 'Customer not found') {
      return NextResponse.json({ error: 'Customer not found.' }, { status: 404 });
    }
    return NextResponse.json({ error: 'Could not update the store.' }, { status: 500 });
  }
}

'use client';
import { useState, useEffect } from 'react';
import { Order, Customer, RoastBatchStatus } from '@/lib/store';

type View = 'orders' | 'customers';

export default function Page() {
  const [view, setView] = useState<View>('orders');
  const [orders, setOrders] = useState<Order[]>([]);
  const [customers, setCustomers] = useState<Customer[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [search, setSearch] = useState<string>('');
  const [statusFilter, setStatusFilter] = useState<RoastBatchStatus | 'All'>('All');
  const [sortKey, setSortKey] = useState<keyof Order>('subscriptionDate');
  const [sortDir, setSortDir] = useState<'asc' | 'desc'>('asc');

  const fetchData = async () => {
    setLoading(true);
    setError(null);
    try {
      if (view === 'orders') {
        const res = await fetch('/api/data?entity=orders');
        if (!res.ok) throw new Error('Failed to load orders');
        const data: Order[] = await res.json();
        setOrders(data);
      } else {
        const res = await fetch('/api/data?entity=customers');
        if (!res.ok) throw new Error('Failed to load customers');
        const data: Customer[] = await res.json();
        setCustomers(data);
      }
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [view]);

  const filteredOrders = orders
    .filter(o => (statusFilter === 'All' ? true : o.status === statusFilter))
    .filter(o => {
      const term = search.toLowerCase();
      return (
        o.id.toLowerCase().includes(term) ||
        o.customerId.toLowerCase().includes(term) ||
        o.roastBatchId.toLowerCase().includes(term)
      );
    })
    .sort((a, b) => {
      const aVal = a[sortKey];
      const bVal = b[sortKey];
      if (aVal < bVal) return sortDir === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortDir === 'asc' ? 1 : -1;
      return 0;
    });

  const filteredCustomers = customers
    .filter(c => {
      const term = search.toLowerCase();
      return (
        c.name.toLowerCase().includes(term) ||
        c.email.toLowerCase().includes(term) ||
        c.address.toLowerCase().includes(term) ||
        c.subscriptionPlan.toLowerCase().includes(term)
      );
    })
    .sort((a, b) => {
      const aVal = a[sortKey as keyof Customer];
      const bVal = b[sortKey as keyof Customer];
      if (aVal < bVal) return sortDir === 'asc' ? -1 : 1;
      if (aVal > bVal) return sortDir === 'asc' ? 1 : -1;
      return 0;
    });

  const toggleSort = (key: keyof Order) => {
    if (sortKey === key) {
      setSortDir(prev => (prev === 'asc' ? 'desc' : 'asc'));
    } else {
      setSortKey(key);
      setSortDir('asc');
    }
  };

  const updateStatus = async (id: string, status: RoastBatchStatus) => {
    try {
      const res = await fetch('/api/data?entity=orders', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id, updates: { status } }),
      });
      if (!res.ok) throw new Error('Update failed');
      await fetchData();
    } catch (e: any) {
      alert(e.message);
    }
  };

  const exportCSV = () => {
    const rows = view === 'orders' ? filteredOrders : filteredCustomers;
    if (rows.length === 0) return;
    const headers = Object.keys(rows[0]);
    const csv = [
      headers.join(','),
      ...rows.map(r => headers.map(h => `"${String((r as any)[h]).replace(/"/g, '""')}"`).join(',')),
    ].join('\n');
    const blob = new Blob([csv], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = view === 'orders' ? 'orders.csv' : 'customers.csv';
    a.click();
    URL.revokeObjectURL(url);
  };

  const revenue = filteredOrders.reduce((sum, o) => sum + o.totalPrice, 0);

  return (
    <div className="container">
      <aside className="sidebar">
        <h2>Ember &amp; Oak</h2>
        <nav>
          <button className="button" onClick={() => setView('orders')} style={{ marginBottom: '8px' }}>
            Orders
          </button>
          <button className="button" onClick={() => setView('customers')}>
            Customers
          </button>
        </nav>
      </aside>
      <main className="main">
        <header>
          <h1>{view === 'orders' ? "This Week's Subscription Orders" : 'Customer Directory'}</h1>
          <div style={{ marginBottom: '8px' }}>
            <input
              className="input"
              placeholder="Search…"
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
            <button className="button" onClick={exportCSV} style={{ marginLeft: '8px' }}>
              Export CSV
            </button>
          </div>
          {view === 'orders' && (
            <div style={{ marginBottom: '8px' }}>
              {(['All', 'Pending', 'Roasting', 'Ready', 'Shipped'] as const).map(status => (
                <span
                  key={status}
                  className={`filter-chip ${statusFilter === status ? 'active' : ''}`}
                  onClick={() => setStatusFilter(status)}
                >
                  {status}
                </span>
              ))}
            </div>
          )}
        </header>

        {loading && <p>Loading…</p>}
        {error && <p style={{ color: 'red' }}>{error}</p>}

        {view === 'orders' && (
          <>
            <p>
              Revenue this view: <strong>${revenue.toFixed(2)}</strong>
            </p>
            {filteredOrders.length === 0 ? (
              <p>No orders match the current criteria.</p>
            ) : (
              <table className="table">
                <thead>
                  <tr>
                    <th onClick={() => toggleSort('id')}>Order ID</th>
                    <th onClick={() => toggleSort('customerId')}>Customer</th>
                    <th onClick={() => toggleSort('subscriptionDate')}>Date</th>
                    <th onClick={() => toggleSort('quantityG')}>Qty (g)</th>
                    <th onClick={() => toggleSort('roastBatchId')}>Batch</th>
                    <th>Status</th>
                    <th onClick={() => toggleSort('totalPrice')}>Total</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredOrders.map(o => (
                    <tr key={o.id}>
                      <td>{o.id}</td>
                      <td>{o.customerId}</td>
                      <td>{new Date(o.subscriptionDate).toLocaleDateString()}</td>
                      <td>{o.quantityG}</td>
                      <td>{o.roastBatchId}</td>
                      <td>
                        <select
                          className="input"
                          value={o.status}
                          onChange={e => updateStatus(o.id, e.target.value as RoastBatchStatus)}
                        >
                          {(['Pending', 'Roasting', 'Ready', 'Shipped'] as RoastBatchStatus[]).map(s => (
                            <option key={s} value={s}>
                              {s}
                            </option>
                          ))}
                        </select>
                      </td>
                      <td>${o.totalPrice.toFixed(2)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </>
        )}

        {view === 'customers' && (
          <>
            {filteredCustomers.length === 0 ? (
              <p>No customers match the current criteria.</p>
            ) : (
              <table className="table">
                <thead>
                  <tr>
                    <th onClick={() => toggleSort('id')}>ID</th>
                    <th onClick={() => toggleSort('name')}>Name</th>
                    <th onClick={() => toggleSort('email')}>Email</th>
                    <th onClick={() => toggleSort('address')}>Address</th>
                    <th onClick={() => toggleSort('subscriptionPlan')}>Plan</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredCustomers.map(c => (
                    <tr key={c.id}>
                      <td>{c.id}</td>
                      <td>{c.name}</td>
                      <td>{c.email}</td>
                      <td>{c.address}</td>
                      <td>{c.subscriptionPlan}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </>
        )}
      </main>
    </div>
  );
}

import type { Metadata } from 'next';
import './globals.css';

export const metadata: Metadata = {
  title: {
    default: 'Order Desk — Ember & Oak',
    template: '%s — Ember & Oak',
  },
  description: 'Manage weekly subscription orders, roast batches, and customers for Ember & Oak small-batch coffee roastery.',
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}
